def apply(t, old, new, nth, name):
    if nth is None:
        assert t.count(old) == 1, (name, t.count(old))
        return t.replace(old, new)
    parts = t.split(old)
    assert len(parts) > nth + 1, (name, len(parts))
    return old.join(parts[:nth + 1]) + new + old.join(parts[nth + 1:])
